import sys

def solve():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    L, C = data[0], data[1]
    P = data[2]

    black = [[False] * C for _ in range(L)]
    idx = 3
    for _ in range(P):
        x = data[idx] - 1
        y = data[idx + 1] - 1
        idx += 2
        black[x][y] = True

    eligible_masks = [0] * L

    for r in range(L):
        mask = 0
        for c in range(C):
            if black[r][c]:
                continue

            ok = False
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < L and 0 <= nc < C and black[nr][nc]:
                    ok = True
                    break

            if ok:
                mask |= 1 << c

        eligible_masks[r] = mask

    popcount = [bin(i).count("1") for i in range(1 << C)]
    possible = [[] for _ in range(L)]

    for r in range(L):
        em = eligible_masks[r]
        for m in range(1 << C):
            if (m & ~em) == 0 and (m & (m << 1)) == 0:
                possible[r].append(m)

    dp = {0: 0}

    for r in range(L):
        ndp = {}
        for prev, value in dp.items():
            for m in possible[r]:
                if m & prev == 0:
                    new_value = value + popcount[m]
                    if new_value > ndp.get(m, -1):
                        ndp[m] = new_value
        dp = ndp

    print(max(dp.values()))

if __name__ == "__main__":
    solve()
